from fractions import Fraction

flip = {"<": ">", "<=": ">=", ">": "<", ">=": "<="}

def holds(left, rel, right):
    if rel == "<":
        return left < right
    if rel == "<=":
        return left <= right
    if rel == ">":
        return left > right
    return left >= right

def solve(case, a, b, rel, c, d):
    print(case)
    k = a - c
    m = d - b
    print(f"  collect x terms on the left, numbers on the right: {k}x {rel} {m}")
    if k == 0:
        if holds(0, rel, m):
            print(f"  0 {rel} {m} is true for every x: all real numbers")
        else:
            print(f"  0 {rel} {m} is false for every x: no solution")
        return
    bound = Fraction(m, k)
    if k > 0:
        answer = rel
        print(f"  divide by {k}, a positive, so keep the sign: x {answer} {bound}")
    else:
        answer = flip[rel]
        print(f"  divide by {k}, a negative, so flip the sign: x {answer} {bound}")
    agree = 0
    for x in range(-25, 26):
        agree = agree + (holds(a * x + b, rel, c * x + d) == holds(x, answer, bound))
    print(f"  check: agrees with the original on {agree} of 51 integers")

solve("Case 1 · the plain case: 3x + 4 < 19", 3, 4, "<", 0, 19)
solve("Case 2 · a negative coefficient: 7 - 2x < 1", -2, 7, "<", 0, 1)
solve("Case 3 · x on both sides: 5x - 3 >= 2x + 9", 5, -3, ">=", 2, 9)
solve("Case 4 · a fraction answer: -4x <= 6", -4, 0, "<=", 0, 6)
solve("Case 5 · always true: 2x + 1 < 2x + 4", 2, 1, "<", 2, 4)
solve("Case 6 · never true: 2x + 4 < 2x + 1", 2, 4, "<", 2, 1)
solve("Case 7 · a word problem: 500 - 20t < 140", -20, 500, "<", 0, 140)

