practice.solution:
from fractions import Fraction

flip = {"<": ">", "<=": ">=", ">": "<", ">=": "<="}

def holds(left, rel, right):
    if rel == "<":
        return left < right
    if rel == "<=":
        return left <= right
    if rel == ">":
        return left > right
    return left >= right

n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    rel = input()
    c = int(input())
    d = int(input())
    k = a - c
    m = d - b
    print(f"collect: {k}x {rel} {m}")
    if k == 0:
        if holds(0, rel, m):
            print("answer: all real numbers")
        else:
            print("answer: no solution")
    elif k > 0:
        print(f"answer: x {rel} {Fraction(m, k)}")
    else:
        print(f"answer: x {flip[rel]} {Fraction(m, k)}")

