from fractions import Fraction

n = int(input())
for i in range(n):
    a = int(input())
    b = int(input())
    rel = input()
    r = int(input())
    if r < 0:
        if rel == "<" or rel == "<=":
            print("no solution")
        else:
            print("all real numbers")
    elif r == 0 and rel == "<":
        print("no solution")
    else:
        lo = Fraction(-r - b, a)
        hi = Fraction(r - b, a)
        if lo > hi:
            lo, hi = hi, lo
        if rel == "<":
            print(f"({lo}, {hi})")
        elif rel == "<=":
            print(f"[{lo}, {hi}]")
        elif rel == ">":
            print(f"(-inf, {lo}) U ({hi}, inf)")
        else:
            print(f"(-inf, {lo}] U [{hi}, inf)")
